/**
 * Ambient declarations for style imports used by the Expo template.
 * Metro resolves these at build time; TypeScript only needs to know they exist.
 *
 * Deliberately a global script file (no imports/exports) so the wildcard
 * module declarations are visible everywhere without explicit imports.
 */
declare module '*.css';
declare module '*.module.css';
declare module '@/global.css';
